connect.lines:
with start: github-webhook-start | inbound.context={{payload}} | token={{secrets.GITHUB_WEBHOOK_TOKEN}}
with send: slack chat.postMessage | token={{secrets.SLACK_TOKEN}} | data.text=="Open Issues" + timeslot + "-" + repo | data.channel=#triage
with fetch: http GET /repos/:owner/:repo/issues | api=github | ghtoken={{secrets.GITHUB_TOKEN}} | params.fetch=open | params.fetch=per_page=100 | result=issues: response.body
with charge: slack chat.postMessage | token={{secrets.SLACK_TOKEN}} | data.text==map(i, i.title, i).reduce((a,b)=>a+"\n- "+b, "") | data.channel=#triage | mode=messageBlock | data.blockContent=={type: "section", text: {type: "mrkdwn", text: "{{issues}}"}}

